package com.celica.dash.data

import android.content.Context
import org.json.JSONArray
import org.json.JSONObject

/**
 * The car's reference data, read from the site's static API bundled in the APK
 * (assets/site/api, generated by tools/export_api.py from docs/data). Loaded once, lazily.
 *
 * The HTML fields (issue symptom/cause/check/fix) are kept as HTML and rendered with
 * AnnotatedString.fromHtml - the site's own prose, minus its layout.
 */
class SiteData(private val ctx: Context) {

    // ---- fusebox ----------------------------------------------------------------------------
    class FuseSlot(val n: Int, val amp: Float?, val name: String, val cls: String?, val conf: String?, val load: Pair<Float, Float>?, val what: String?, val note: String?)
    class FuseClass(val id: String, val name: String, val desc: String)
    /** The lid label's arrangement: a wide slot or two, rows of full-size cards, then rows of small ones. */
    class FuseLayout(val wide: List<Int>, val rows: List<List<Int>>, val small: List<List<Int>>, val smallCaption: String, val first: Int)
    class Fusebox(val boxName: String, val where: String, val caption: String, val manualFig: Int?, val manualNote: String?, val classes: List<FuseClass>, val taps: Set<Int>, val slots: List<FuseSlot>, val layout: FuseLayout)

    /** The car pack's fusebox, or null when the pack has none. */
    val fusebox: Fusebox? by lazy {
        val j = json("api/fuses.json") ?: return@lazy null
        val box = j.optJSONObject("box") ?: return@lazy null
        val classes = j.getJSONObject("classes").let { c -> c.keys().asSequence().map { k -> FuseClass(k, c.getJSONObject(k).getString("name"), c.getJSONObject(k).getString("desc")) }.toList() }
        val taps = j.getJSONArray("taps").let { a -> (0 until a.length()).map { a.getInt(it) }.toSet() }
        val slots = j.getJSONArray("slots").objects().map { s ->
            FuseSlot(
                s.getInt("n"), s.optDouble("amp").takeIf { !it.isNaN() }?.toFloat(), s.optString("name", "—"),
                s.optString("cls").takeIf { it.isNotEmpty() && it != "null" }, s.optString("conf").takeIf { it.isNotEmpty() && it != "null" },
                s.optJSONArray("load")?.let { l -> l.getDouble(0).toFloat() to l.getDouble(1).toFloat() },
                s.optString("what").takeIf { it.isNotEmpty() && it != "null" }, s.optString("note").takeIf { it.isNotEmpty() && it != "null" },
            )
        }
        val ints = { a: JSONArray? -> a?.let { arr -> (0 until arr.length()).map { arr.getInt(it) } } ?: emptyList() }
        val lists = { a: JSONArray? -> a?.let { arr -> (0 until arr.length()).map { ints(arr.getJSONArray(it)) } } ?: emptyList() }
        val lj = j.optJSONObject("layout")
        // a pack without a layout gets its slots in rows of nine, in number order
        val layout = if (lj != null) FuseLayout(ints(lj.optJSONArray("wide")), lists(lj.optJSONArray("rows")), lists(lj.optJSONArray("small")), lj.optString("smallCaption"), lj.optInt("first", slots.firstOrNull()?.n ?: 1))
        else FuseLayout(emptyList(), slots.map { it.n }.chunked(9), emptyList(), "", slots.firstOrNull()?.n ?: 1)
        Fusebox(
            box.optString("name", "Fusebox"), box.optString("where"), box.optString("caption").ifBlank { box.optString("where").uppercase() },
            box.optInt("manualFig", -1).takeIf { it >= 0 }, box.optString("manualNote"), classes, taps, slots, layout,
        )
    }

    // ---- issues -----------------------------------------------------------------------------
    class Hot(val x: Float, val y: Float, val z: Float, val label: String)
    class FigRef(val page: Int, val caption: String)
    class Step(val t: String, val hint: String?)
    class Issue(
        val id: String, val title: String, val area: String, val severity: String, val status: String, val since: String,
        val blurb: String, val hot: Hot?, val symptom: String, val cause: String, val check: List<Step>, val fix: String,
        val figs: List<FigRef>,
    )

    val issues: List<Issue> by lazy {
        (json("api/issues.json")?.optJSONArray("issues")?.objects() ?: emptyList()).map { i ->
            Issue(
                i.getString("id"), i.getString("title"), i.optString("area"), i.optString("severity", "attention"), i.optString("status", "open"),
                i.optString("since"), i.optString("blurb"),
                i.optJSONObject("hot")?.let { h -> Hot(h.getDouble("x").toFloat(), h.getDouble("y").toFloat(), h.getDouble("z").toFloat(), h.optString("label")) },
                i.optString("symptom"), i.optString("cause"),
                i.optJSONArray("check")?.objects()?.map { c -> Step(c.getString("t"), c.optString("hint").takeIf { it.isNotEmpty() }) } ?: emptyList(),
                i.optString("fix"),
                i.optJSONArray("figs")?.objects()?.map { f -> FigRef(f.getInt("p"), f.optString("c")) } ?: emptyList(),
            )
        }
    }

    // ---- specs ------------------------------------------------------------------------------
    class SpecRow(val k: String, val v: String, val v2: String?, val fig: Int?, val note: String?)
    class SpecGroup(val id: String, val name: String, val sub: String?, val fig: Int?, val rows: List<SpecRow>)

    val specs: List<SpecGroup> by lazy {
        (json("api/specs.json")?.optJSONArray("groups")?.objects() ?: emptyList()).map { g ->
            SpecGroup(
                g.getString("id"), unescape(g.getString("name")), g.optString("sub").takeIf { it.isNotEmpty() }, g.optInt("fig", -1).takeIf { it >= 0 },
                g.getJSONArray("rows").objects().map { r ->
                    SpecRow(unescape(r.getString("k")), unescape(r.getString("v")), r.optString("v2").takeIf { it.isNotEmpty() }?.let(::unescape), r.optInt("fig", -1).takeIf { it >= 0 }, r.optString("note").takeIf { it.isNotEmpty() }?.let(::unescape))
                },
            )
        }
    }

    // ---- maintenance checklist --------------------------------------------------------------
    class CheckItem(val t: String, val hint: String?)
    class CheckGroup(val id: String, val name: String, val code: String?, val fig: Int?, val kind: String?, val items: List<CheckItem>)

    val checks: List<CheckGroup> by lazy {
        (json("api/maintenance.json")?.optJSONArray("groups")?.objects() ?: emptyList()).map { g ->
            CheckGroup(
                g.getString("id"), g.getString("name"), g.optString("code").takeIf { it.isNotEmpty() }, g.optInt("fig", -1).takeIf { it >= 0 }, g.optString("kind").takeIf { it.isNotEmpty() },
                g.getJSONArray("items").objects().map { CheckItem(it.getString("t"), it.optString("hint").takeIf { h -> h.isNotEmpty() }) },
            )
        }
    }

    // ---- manual -----------------------------------------------------------------------------
    class Sub(val title: String, val a: Int, val b: Int, val figures: Int)
    class Section(val code: String, val name: String, val a: Int, val b: Int, val figures: Int, val subs: List<Sub>)
    class PageIndex(val page: Int, val code: String, val printed: Boolean, val heading: String)
    class Page(val page: Int, val code: String, val codeApprox: String?, val printed: Boolean, val sectionCode: String?, val heading: String, val hasFigure: Boolean, val text: String)

    val sections: List<Section> by lazy {
        (json("api/manual/sections.json")?.optJSONArray("sections")?.objects() ?: emptyList()).map { s ->
            Section(
                s.getString("code"), s.getString("name"), s.getInt("a"), s.getInt("b"), s.optInt("f"),
                s.optJSONArray("subs")?.objects()?.map { Sub(it.getString("t"), it.getInt("a"), it.getInt("b"), it.optInt("f")) } ?: emptyList(),
            )
        }
    }

    val pageIndex: List<PageIndex> by lazy {
        (json("api/manual/pages.json")?.optJSONArray("pages")?.objects() ?: emptyList()).map {
            PageIndex(it.getInt("page"), it.optString("code"), it.optBoolean("codeIsPrinted"), it.optString("heading"))
        }
    }
    /** Pages in the manual; 0 when the pack has none, and then the Manual is not offered at all. */
    val manualTotal: Int by lazy { json("api/manual/pages.json")?.optInt("count", 0) ?: 0 }
    val hasManual: Boolean get() = manualTotal > 0 && sections.isNotEmpty()

    /** A page, or a blank one for a number the pack does not have. */
    fun page(n: Int): Page {
        val p = json("api/manual/pages/$n.json") ?: return Page(n, "", null, false, null, "", false, "")
        return Page(
            p.getInt("page"), p.optString("code"), p.optString("codeApprox").takeIf { it.isNotEmpty() }, p.optBoolean("codeIsPrinted"),
            p.optJSONObject("section")?.optString("code"), p.optString("heading"), p.optBoolean("hasFigure"), p.optString("text"),
        )
    }

    /** Every page's text, for search. About 7 MB of JSON; read once on a background thread. */
    val pageTexts: Map<Int, String> by lazy {
        (0 until manualTotal).associateWith { n -> json("api/manual/pages/$n.json")?.optString("text") ?: "" }
    }

    fun figurePath(page: Int) = "site/assets/fig/p%04d.png".format(page)

    // ---- helpers ----------------------------------------------------------------------------
    /** The file as JSON, or null when the pack has no such file or it does not parse. */
    private fun json(path: String): JSONObject? = runCatching { JSONObject(ctx.assets.open("site/$path").bufferedReader().readText()) }.getOrNull()
    private fun JSONArray.objects(): List<JSONObject> = (0 until length()).map { getJSONObject(it) }
    private fun unescape(s: String) = s.replace("&amp;", "&").replace("&lt;", "<").replace("&gt;", ">").replace("&#39;", "'").replace("&quot;", "\"")
}
